<?php
require_once dirname(__DIR__).'/generator.php';
function cutExpect($condition,string$message):void{if(!$condition)throw new RuntimeException($message);}
$industries=[
 ['id'=>1,'industry_name'=>'Main 1','industry_type'=>'Staging','ships_services'=>'all','receives_services'=>'all','track_capacity'=>50],
 ['id'=>2,'industry_name'=>'Cargill','industry_type'=>'Industry','ships_services'=>'grain','receives_services'=>'grain','track_capacity'=>8],
 ['id'=>3,'industry_name'=>'Flour Mill','industry_type'=>'Industry','ships_services'=>'grain','receives_services'=>'grain','track_capacity'=>20],
 ['id'=>4,'industry_name'=>'Engine Terminal','industry_type'=>'Yard','ships_services'=>'grain','receives_services'=>'grain','track_capacity'=>50],
 ['id'=>5,'industry_name'=>'Unrelated Warehouse','industry_type'=>'Industry','ships_services'=>'goods','receives_services'=>'goods','track_capacity'=>50],
 ['id'=>6,'industry_name'=>'Local Main 2','industry_type'=>'Main Track','ships_services'=>'all','receives_services'=>'all','track_capacity'=>50],
];
$industryNames=array_column($industries,'industry_name','id');
$car=static fn(int$id,int$location,string$service='grain',string$load='Loaded'):array=>['id'=>$id,'reporting_marks'=>'CUT','road_number'=>(string)$id,'equipment_type'=>'Hopper','operations_service'=>$service,'load_status'=>$load,'current_industry_id'=>$location,'current_track'=>'Main 1','origin_name'=>$industryNames[$location],'photo_filename'=>null];
$startingIds=range(1,15);$cars=[];foreach($startingIds as$id)$cars[]=$car($id,1,$id===15?'coal':'grain');$cars[]=$car(100,4);$cars[]=$car(101,1);$cars[]=$car(102,5,'goods','Empty');foreach(range(200,204)as$id)$cars[]=$car($id,2,'grain','Empty');foreach(range(205,209)as$id)$cars[]=$car($id,3,'grain','Empty');$cars[]=$car(210,6,'grain','Empty');
$baseAssignment=['start_method'=>'prepared_cut','work_scope'=>'entire_railroad','requested_car_count'=>0,'prepared_cut_car_count'=>5,'operating_base_industry_id'=>4,'end_industry_id'=>4,'prepared_cut_industry_id'=>1,'prepared_cut_track'=>'Main 1'];
$entire=ttChooseOperationsMoves($baseAssignment,$cars,$industries,$startingIds,[]);
$entirePulls=array_values(array_filter($entire['moves'],static fn($m)=>$m['action']==='PULL'));$entireSpots=array_values(array_filter($entire['moves'],static fn($m)=>$m['action']==='SPOT'));cutExpect(count($entirePulls)===5&&count($entireSpots)===5,'Five prepared-cut Spots must produce five required empty-car Pulls even when Maximum Additional Pickups is zero.');
$entireIds=array_column($entire['moves'],'equipment_id');cutExpect(!in_array(100,$entireIds,true)&&!in_array(101,$entireIds,true)&&!in_array(102,$entireIds,true)&&!in_array(210,$entireIds,true),'Cars at the base, cut location, unrelated locations, or a support main must not become opportunistic work.');
cutExpect(count($entireIds)===count(array_unique($entireIds)),'Each prepared-cut car may receive at most one movement.');
cutExpect(array_column($entireSpots,'equipment_id')===range(1,5),'Prepared Cut Cars to Switch must cap Spot moves while preserving saved cut order.');
$tenAssignment=$baseAssignment;$tenAssignment['prepared_cut_car_count']=10;$ten=ttChooseOperationsMoves($tenAssignment,$cars,$industries,$startingIds,[]);$tenPulls=array_values(array_filter($ten['moves'],static fn($m)=>$m['action']==='PULL'));$tenSpots=array_values(array_filter($ten['moves'],static fn($m)=>$m['action']==='SPOT'));
cutExpect(count($tenSpots)===10&&array_column($tenSpots,'equipment_id')===range(1,10),'Raising Prepared Cut Cars to Switch to ten must create ten loaded prepared-cut Spots in saved order.');cutExpect(count($tenPulls)===10,'Each of ten loaded Spots must have a required empty Pull that is not limited by Maximum Additional Pickups.');
foreach($tenPulls as$move)cutExpect((int)$move['destination_industry_id']===4,'Required empty Pulls must use the configured terminal or operating base when it has capacity.');
foreach($tenSpots as$move)cutExpect(in_array((int)$move['destination_industry_id'],[2,3],true),'Entire Railroad Spots must use actual customer industries only.');cutExpect(count(array_filter($tenSpots,static fn($m)=>(int)$m['destination_industry_id']===6))===0,'Local Main 2 must never be selected as a customer Spot destination.');
$tenLocations=[];foreach($ten['moves']as$move)$tenLocations[$move['work_location']][]=$move['action'];cutExpect(array_keys($tenLocations)===['Cargill','Flour Mill'],'Exchanges must use deterministic customer ordering.');foreach($tenLocations as$actions){$firstSpot=array_search('SPOT',$actions,true);cutExpect($firstSpot!==false,'Every exchange location must include a Spot.');foreach(array_slice($actions,0,$firstSpot)as$action)cutExpect($action==='PULL','Required empty Pulls must precede Spots.');foreach(array_slice($actions,$firstSpot)as$action)cutExpect($action==='SPOT','No Pull may appear after Spots begin at an exchange location.');}
$pairs=[];foreach($ten['moves']as$move)$pairs[$move['movement_group']][]=$move['action'];foreach($pairs as$actions)cutExpect($actions===['PULL','SPOT'],'Every loaded Spot must remain paired with its required empty Pull.');
$reservedEmptyAssignment=$baseAssignment;$reservedEmptyAssignment['prepared_cut_car_count']=1;$reservedEmpty=ttChooseOperationsMoves($reservedEmptyAssignment,$cars,$industries,$startingIds,[200]);cutExpect(!in_array(200,array_column($reservedEmpty['moves'],'equipment_id'),true)&&count($reservedEmpty['moves'])===2,'A reserved empty must not be used, and no substitute beyond another valid empty at the same customer may be invented.');
$incompatibleAssignment=$baseAssignment;$incompatibleAssignment['prepared_cut_car_count']=15;$incompatible=ttChooseOperationsMoves($incompatibleAssignment,$cars,$industries,$startingIds,[]);
cutExpect(strpos(implode(' ',$incompatible['diagnostics']),'No valid loaded-for-empty customer exchange was available for prepared-cut car CUT 15')!==false,'An unmatched prepared-cut car must receive the named no-exchange diagnostic and remain with the train.');
$byLocation=[];foreach($entireSpots as$move)$byLocation[$move['work_location']][]=$move['equipment_id'];foreach($byLocation as$ids)cutExpect($ids===array_values(array_filter($startingIds,static fn($id)=>in_array($id,$ids,true))),'Prepared-cut order must be preserved within each Spot group.');
