cutExpect(count(array_filter($entire['moves'],static fn($m)=>$m['destination_industry_id']===2))<=8,'Projected destination capacity must be respected.');

$routeStops=[
 ['id'=>1,'industry_id'=>2,'sequence_number'=>1,'exchange_enabled'=>0,'outbound_load_status'=>'Empty','inbound_load_status'=>'Loaded','pull_destination_mode'=>'operating_base','pull_destination_industry_id'=>null,'replacement_source_mode'=>'prepared_cut','replacement_source_industry_id'=>null],
 ['id'=>2,'industry_id'=>3,'sequence_number'=>2,'exchange_enabled'=>0,'outbound_load_status'=>'Empty','inbound_load_status'=>'Loaded','pull_destination_mode'=>'operating_base','pull_destination_industry_id'=>null,'replacement_source_mode'=>'prepared_cut','replacement_source_industry_id'=>null],
];
$routeAssignment=$baseAssignment;$routeAssignment['work_scope']='selected_route';$routeAssignment['requested_car_count']=3;$routeAssignment['prepared_cut_car_count']=10;$route=ttChooseOperationsMoves($routeAssignment,$cars,$industries,$startingIds,[],$routeStops);$routeIds=array_column($route['moves'],'equipment_id');$pulls=array_values(array_filter($route['moves'],static fn($m)=>$m['action']==='PULL'));$spots=array_values(array_filter($route['moves'],static fn($m)=>$m['action']==='SPOT'));
cutExpect(count($pulls)===3,'requested_car_count must limit only additional route pickups.');
cutExpect(count($spots)===10,'Prepared Cut Cars to Switch must cap route Spot work from the prepared cut.');
cutExpect(!in_array(102,$routeIds,true),'Pulls must not originate from an unconfigured route location.');
foreach($spots as$move)cutExpect(in_array($move['destination_industry_id'],[2,3],true),'Selected Route Spots must use industries in the selected Operating Areas only.');
$locations=[];foreach($route['moves']as$move){$locations[$move['work_location']][]=$move['action'];}cutExpect(array_keys($locations)===['Cargill','Flour Mill'],'Route work must follow configured stop order and visit each location once.');foreach($locations as$actions){$firstSpot=array_search('SPOT',$actions,true);if($firstSpot!==false)foreach(array_slice($actions,$firstSpot)as$action)cutExpect($action==='SPOT','Pulls must precede Spots at each route stop.');}
cutExpect(count($routeIds)===count(array_unique($routeIds)),'Prepared-cut and pickup cars must not receive duplicate work.');

$singleEmpty=$car(200,2,'grain','Empty');$correctTrack=ttChooseOperationsMoves($baseAssignment,[$car(1,1),$singleEmpty],$industries,[1],[]);cutExpect(count($correctTrack['moves'])===2,'A prepared-cut car at the saved location and track must remain eligible for a valid exchange.');
$wrongTrackCar=$car(1,1);$wrongTrackCar['current_track']='Track 2';$wrongTrack=ttChooseOperationsMoves($baseAssignment,[$wrongTrackCar,$singleEmpty],$industries,[1],[]);cutExpect(count($wrongTrack['moves'])===0,'A prepared-cut car on another track must not receive a move.');cutExpect(strpos(implode(' ',$wrongTrack['diagnostics']),'Prepared-cut car CUT 1 is no longer on the saved cut track Main 1')!==false,'Wrong-track diagnostics must name the car and authoritative saved track.');
$blankTrackAssignment=$baseAssignment;$blankTrackAssignment['prepared_cut_track']='';$blankTrack=ttChooseOperationsMoves($blankTrackAssignment,[$wrongTrackCar,$singleEmpty],$industries,[1],[]);cutExpect(count($blankTrack['moves'])===2,'A blank saved cut track must use location-only validation.');

cutExpect(ttPreparedCutStatusIsAssigned(['status'=>'assigned']),'An assigned Prepared Cut must be accepted.');foreach(['ready','released','dissolved','in_use','unexpected']as$status)cutExpect(!ttPreparedCutStatusIsAssigned(['status'=>$status]),$status.' Prepared Cuts must be rejected.');cutExpect(!ttPreparedCutStatusIsAssigned(null),'A missing Prepared Cut must be rejected.');
$duplicateStops=[$routeStops[0],array_merge($routeStops[0],['id'=>99,'sequence_number'=>2])];$duplicateRejected=false;try{ttChooseOperationsMoves($routeAssignment,$cars,$industries,$startingIds,[],$duplicateStops);}catch(RuntimeException$e){$duplicateRejected=strpos($e->getMessage(),'Duplicate active industry in the selected Route Areas: Cargill')!==false;}cutExpect($duplicateRejected,'Duplicate Selected Route locations must be rejected by name before any group can be overwritten.');

$same=ttPreparedCutPickupInstruction(['operating_base_industry_id'=>1,'base_name'=>'Main 1'],['current_industry_id'=>1,'industry_name'=>'Main 1','current_track'=>'Track 2','cut_number'=>'CUT-00001','name'=>'Main cut','car_count'=>15]);cutExpect(strpos($same,'Track 2')!==false&&strpos($same,'CUT-00001')!==false,'Same-location pickup instruction must use the saved cut track and identity.');
$travel=ttPreparedCutPickupInstruction(['operating_base_industry_id'=>4,'base_name'=>'Engine Terminal'],['current_industry_id'=>1,'industry_name'=>'Main 1','current_track'=>'Track 2','cut_number'=>'CUT-00001','name'=>'Main cut','car_count'=>15]);cutExpect(strpos($travel,'Run light from Engine Terminal to Main 1 on Track 2')!==false,'Travel pickup instruction must use actual base, cut location, and cut track.');
$generate=file_get_contents(dirname(__DIR__).'/generate.php');$routeEditor=file_get_contents(dirname(__DIR__,2).'/jobs/route.php');$sessionForm=file_get_contents(dirname(__DIR__).'/session_edit.php');$editForm=file_get_contents(dirname(__DIR__).'/assignment_edit.php');$formJs=file_get_contents(dirname(__DIR__,2).'/assets/js/assignment-form.js');cutExpect(strpos($generate,'count($plan[\'moves\'])')!==false,'planned_move_count must count equipment movements only.');cutExpect(strpos($generate,"'instruction-pickup',null")!==false,'Pickup instruction must remain a non-equipment row.');cutExpect(strpos($generate,'$preparedCut[\'current_track\']')!==false,'Pickup row must use the Prepared Cut track.');cutExpect(strpos($generate,'Maximum additional pickups')!==false&&strpos($generate,'Starting train')!==false&&strpos($generate,'Prepared cut cars to switch')!==false,'Generation page must show prepared-cut-specific details.');cutExpect(strpos($sessionForm,'Prepared Cut Cars to Switch')!==false&&strpos($editForm,'Prepared Cut Cars to Switch')!==false&&strpos($sessionForm,'tt-prepared-pickup-help')!==false&&strpos($editForm,'tt-prepared-pickup-help')!==false,'Create/Edit must show separate prepared-cut and additional-pickup limits.');cutExpect(strpos($formJs,"limit.value='0'")!==false&&strpos($formJs,'!form.dataset.assignmentEdit')!==false,'New prepared-cut assignments must default additional pickups to zero without overwriting edits.');cutExpect(substr_count($generate,'ttLoadAssignmentPreparedCut(')>=3&&strpos($generate,"try{\$preparedCut=ttLoadAssignmentPreparedCut")!==false&&strpos($generate,'ttLoadAssignmentPreparedCut($pdo,$assignment,$railroadId,true)')!==false,'GET and locked POST must both enforce Prepared Cut status.');cutExpect(strpos($generate,'ORDER BY position FOR UPDATE')!==false&&strpos($generate,"source_type']??'')!=='prepared_cut'")!==false,'POST must lock and revalidate saved Prepared Cut membership in position order.');cutExpect(strpos($routeEditor,'Operating Area')!==false&&strpos($routeEditor,'operating_areas[]')!==false,'The route editor must use automatically derived, multi-selectable Operating Areas.');cutExpect(strpos($generate,'UPDATE equipment SET')===false,'Generation must not update equipment state.');
